import assert from'node:assert/strict';import{readFile,readdir}from'node:fs/promises';import{createHash}from'node:crypto';import{resolve,join}from'node:path';import{fileURLToPath,pathToFileURL}from'node:url';
const sha=s=>createHash('sha256').update(s).digest('hex');const json=async p=>JSON.parse(await readFile(p,'utf8'));const blocks=s=>[...s.matchAll(/<(p|h2|h3|h4|li|summary|pre|tr)\b[^>]*>[\s\S]*?<\/\1>/g)].map(m=>m[0]);
export async function verifyFinal({dist,fixtures}){
 assert.ok(dist&&fixtures,'Explicit actual built dist and fixture directory required');
 const R=(await json(join(fixtures,'records.json'))).records,SR=(await json(join(fixtures,'next-batch-sandbox-record.json'))).records,AP=await json(join(fixtures,'append-manifest.json')),SM=(await json(join(fixtures,'source-block-map.json'))).blocks,V=(await json(join(fixtures,'variant-map.json'))).variants,D=(await json(join(fixtures,'destinations.json'))).destinations,I=(await json(join(fixtures,'identity-baseline.json'))).entries,LM=(await json(join(fixtures,'lead-map.json'))).blocks;
 const E=new Map();for(const f of await readdir(join(dist,'data/chapters')))if(f.endsWith('.json'))for(const e of(await json(join(dist,'data/chapters',f))).entries){assert.ok(!E.has(e.id),'duplicate entry '+e.id);E.set(e.id,e);}
 const catalog=await json(join(dist,'data/catalog.json'));const item=(e,n)=>{const it=E.get(e)?.items?.[n];assert.ok(it,`MISSING_ITEM ${e}/${n}`);return it;};const body=(e,n)=>item(e,n).a;
 const allowed=new Set(['ai-agent-7:2:a','ai-agent-7:2:lead','bg-kafka-4:1:a','own-mysql-ch04:7:a','own-juc-contexts:4:a','own-juc-systems:6:a']);assert.equal(R.length,6);assert.equal(SR.length,1);
 const all=[...R,...SR];for(const r of all){const key=`${r.entryId}:${r.itemIndex}:${r.path[2]}`;assert.ok(allowed.has(key)||(SR.includes(r)&&key==='own-os-sandbox:4:a'),'scope expansion '+key);assert.deepEqual(r.path,['items',r.itemIndex,r.path[2]]);assert.equal(sha(r.before),r.beforeSha256);assert.equal(sha(r.after),r.afterSha256);assert.equal(sha(r.questionGuard),r.questionSha256);const it=item(r.entryId,r.itemIndex);assert.equal(it.q,r.questionGuard);assert.equal(it.id??null,r.questionId??null);assert.ok(it[r.path[2]]===r.after,`UNAPPLIED_OR_CHANGED ${r.entryId}/${r.itemIndex}/${r.path[2]}`);assert.ok(catalog.entries.some(e=>e.id===r.entryId),'missing catalog '+r.entryId);if(r.mode==='append-only-unique-detail')assert.ok(r.after.startsWith(r.before),'canonical prefix changed');if(r.path[2]==='a')for(const m of r.before.matchAll(/\bid="([^"]+)"/g))assert.ok(r.after.includes('id="'+m[1]+'"'),'lost legacy anchor');}
 assert.equal(AP.entryId,'own-distributed-ch06');assert.equal(AP.appends.length,1);const ap=AP.appends[0];assert.equal(ap.expectedIndex,5);assert.equal(ap.questionId,'q-own-distributed-monthly-budget');assert.deepEqual(AP.afterAppendEntry.items.slice(0,AP.beforeEntry.items.length),AP.beforeEntry.items,'compiler full-object prefix changed');assert.equal(AP.beforeEntry.items.length,5);assert.deepEqual(item(AP.entryId,ap.expectedIndex),ap.expectedItem,'real authored question missing or changed');
 for(const row of I)for(const[n,old]of row.questionPrefix.entries()){assert.equal(item(row.entryId,n).q,old.q,'old question/index changed');assert.equal(item(row.entryId,n).id??null,old.id??null,'old question ID changed');}
 const dest=new Map(D.map(d=>[d.key,d]));assert.equal(dest.size,D.length);assert.equal(D.length,93);for(const d of D){assert.equal(d.kind,'substantive-body');assert.match(d.html,/^<(p|li)\b/);assert.equal(sha(d.html),d.sha256);assert.ok(body(d.entryId,d.itemIndex).includes(d.html),'MISSING_SUBSTANTIVE_WITNESS '+d.key);if(d.questionId)assert.equal(item(d.entryId,d.itemIndex).id,d.questionId);}
 const before=R.find(r=>r.entryId==='ai-agent-7'&&r.path[2]==='a').before,b=blocks(before);assert.equal(b.length,110);assert.equal(SM.length,b.length);assert.deepEqual(SM.map(m=>m.sourceBlockIndex),b.map((_,i)=>i));for(const m of SM){assert.equal(m.sourceHtml,b[m.sourceBlockIndex]);assert.equal(sha(m.sourceHtml),m.sourceSha256);assert.ok(m.destinationKeys.length);for(const k of m.destinationKeys)assert.ok(dest.has(k),'unknown semantic destination '+k);}
 assert.equal(V.length,51);assert.equal(new Set(V.map(v=>v.sourceBlockIndex)).size,V.length);for(const v of V){assert.equal(v.sourceHtml,b[v.sourceBlockIndex]);assert.equal(sha(v.sourceHtml),v.sourceSha256);assert.equal(v.sourceWordingHtml,v.sourceHtml.replace(/^<[^>]+>|<\/[^>]+>$/g,''));const d=v.wordingDestination;assert.equal(sha(d.html),d.sha256);assert.ok(d.html.includes(v.sourceWordingHtml),'wording changed');assert.ok(body(d.entryId,d.itemIndex).includes(d.html),'MISSING_EXACT_WORDING '+v.sourceBlockIndex);assert.ok(v.substantiveDestinationKeys.length);for(const k of v.substantiveDestinationKeys)assert.ok(dest.has(k),'wording only, no answer');}
 const lr=R.find(r=>r.entryId==='ai-agent-7'&&r.path[2]==='lead'),lb=blocks(lr.before);assert.equal(LM.length,2);for(const m of LM){assert.equal(m.sourceHtml,lb[m.sourceBlockIndex]);assert.equal(sha(m.sourceHtml),m.sourceSha256);assert.equal(sha(m.destinationHtml),m.destinationSha256);assert.ok(item('ai-agent-7',2).lead.includes(m.destinationHtml));m.substantiveDestinationKeys.forEach(k=>assert.ok(dest.has(k)));}
 const modified=all.filter(r=>r.path[2]==='a').map(r=>r.after).concat(ap.expectedItem.a);for(const a of modified)for(const m of a.matchAll(/href="#\/e\/([^"/]+)(?:\/([^"#]+))?"/g)){const id=decodeURIComponent(m[1]),e=E.get(id);assert.ok(e||catalog.archivedRoutes?.[id],'missing internal route '+m[0]);if(e&&m[2]){const q=decodeURIComponent(m[2]);assert.ok(/^\d+$/.test(q)?e.items?.[Number(q)]:e.items?.some(it=>it.id===q),'missing internal question route '+m[0]);}}
 for(const a of modified)for(const m of a.matchAll(/<(h[1-6]|summary)\b[^>]*>([\s\S]*?)<\/\1>/g))assert.doesNotMatch(m[2],/原问法|保留问法/,'editorial public heading');
 const main=body('ai-agent-7',2),budget=body('own-distributed-ch06',5),cold=body('own-os-sandbox',4);assert.equal((budget.match(/只有预留成功提交/g)||[]).length,1,'duplicated reservation precondition');for(const s of['步骤成功率','重试率','单次成本','排队年龄','分阶段耗时','每租户公平性','累计费用','CPU/堆','连接等待','最终业务成功率'])assert.ok(main.includes(s),'lost observation condition '+s);assert.doesNotMatch(main,/<pre\b|<script\b|https?:\/\//);assert.doesNotMatch(budget,/<pre\b|<script\b/);for(const s of['N/μ','L≈λW','10 个任务/秒','20 秒','200','1.16','1.8','2.08','5.79','NoteWeave','Java 17','不能把 Java 21 虚拟线程写成它已经采用'])assert.ok(main.includes(s),'lost capacity condition '+s);for(const s of['used + reserved + 新预留 ≤ limit','业务时区','跨月','workflowId','唯一约束','短事务','版本 CAS','组织总额','子额度','不能仅等租约过期','共享上游凭据'])assert.ok(budget.includes(s),'lost budget condition '+s);for(const s of['准备期限','执行期限','总 deadline','迟到 ready','当前任务代次','实际回收'])assert.ok(cold.includes(s),'lost cold-start condition '+s);assert.ok(!main.includes('问：lost update'),'monthly budget still inline');assert.ok(!main.includes('同一 SQLite 文件'),'SQLite detail still inline');
 return{status:'PASS_ACTUAL_FINAL_DIST',actualFinalDistAcceptance:true,dist:resolve(dist),overlays:0,siteWrites:0,guardedLeaves:7,actualAuthoredQuestions:1,oldQuestionPrefix:5,sourceBlocks:110,leadBlocks:2,exactQuestionWordings:51,substantiveWitnesses:93,recordsSha256:sha(await readFile(join(fixtures,'records.json'))),verifierSha256:sha(await readFile(join(fixtures,'verify-final-dist.mjs')))};
}
if(process.argv[1]&&import.meta.url===pathToFileURL(resolve(process.argv[1])).href){const args=process.argv.slice(2);for(let i=0;i<args.length;i+=2)assert.ok(['--dist','--fixtures'].includes(args[i])&&args[i+1],'Unsupported argument; no candidate, overlay, or fallback mode');const get=k=>{const i=args.indexOf(k);return i<0?null:args[i+1];};assert.ok(get('--dist'),'Explicit actual built --dist required');try{console.log(JSON.stringify(await verifyFinal({dist:resolve(get('--dist')),fixtures:resolve(get('--fixtures')||fileURLToPath(new URL('.',import.meta.url)))}),null,2));}catch(e){console.error(e.stack);process.exitCode=1;}}
